// Monta o "TOP 3 de agora" a partir do offers.json que o próprio bot publica
// no GitHub Pages. Roda 100% na nuvem: funciona com o PC do Daniel desligado.
//
// Este workflow NÃO republica ofertas individuais — isso duplicaria o que o
// rastreador local e o GitHub Actions já postam. Ele publica um RESUMO, que
// é conteúdo novo e serve de gancho para o CTA dos grupos.
const CONFIG = {
  canal: '@ofertaseletronics',
  grupo_whatsapp: 'https://chat.whatsapp.com/JyJ9uLoZdE5LboH9GjAooC',
  grupo_telegram: 'https://t.me/ofertaseletronics',
  quantidade: 3,
  desconto_minimo: 25,
};

const dados = $json;
const produtos = (dados.products || [])
  .filter(p => p.link && p.titulo && (p.desconto_pct || 0) >= CONFIG.desconto_minimo);

if (!produtos.length) {
  return [{ json: { publicar: false, motivo: 'sem ofertas elegíveis no offers.json' } }];
}

// Não repetir o que já entrou num digest anterior.
const store = $getWorkflowStaticData('global');
store.ja_usados = store.ja_usados || [];
const usados = new Set(store.ja_usados);

const escolhidos = produtos
  .filter(p => !usados.has(p.link))
  .sort((a, b) => (b.desconto_pct || 0) - (a.desconto_pct || 0))
  .slice(0, CONFIG.quantidade);

if (!escolhidos.length) {
  return [{ json: { publicar: false, motivo: 'todas as ofertas já foram usadas num digest' } }];
}

store.ja_usados = [...escolhidos.map(p => p.link), ...store.ja_usados].slice(0, 300);
store.ultimo_digest = new Date().toISOString();

const brl = v => 'R$ ' + Number(v || 0).toFixed(2).replace('.', ',');

// Telegram com parse_mode HTML recusa a mensagem inteira quando `&`, `<`
// ou `>` aparecem crus — inclusive dentro de href. Titulo de produto com
// "&" e mensagem de excecao do Python (`<class 'ValueError'>`) sao o caso
// comum, nao o raro: sem escapar, o alerta simplesmente nao chega.
const esc = (s) => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// matt_source=n8n: o clique vindo deste post fica separado no painel do ML,
// então dá pra medir quanto o reforço na nuvem realmente converte.
const marcar = (url) => {
  try {
    const u = new URL(url);
    // Regra 11: o #fragment de tracking do ML nao vai para o link publicado.
    u.hash = '';
    if (/mercadolivre|mercadolibre|meli\.la/.test(u.hostname)) u.searchParams.set('matt_source', 'n8n');
    else if (/amazon|amzn/.test(u.hostname)) u.searchParams.set('ascsubtag', 'n8n');
    else u.searchParams.set('utm_source', 'n8n');
    return u.toString();
  } catch (e) { return url; }
};

const linhas = escolhidos.map((p, i) =>
  `${i + 1}️⃣ <b>${esc(p.titulo.slice(0, 70))}</b>\n` +
  `    ${brl(p.preco)}` + (p.desconto_pct ? ` — <b>${Math.round(p.desconto_pct)}% OFF</b>` : '') +
  `\n    <a href="${esc(marcar(p.link))}">Ver oferta</a>`
).join('\n\n');

const texto =
  `🔥 <b>TOP ${escolhidos.length} ofertas de agora</b>\n\n` +
  linhas +
  `\n\n📲 Chame os amigos: <a href="${esc(CONFIG.grupo_whatsapp + '?utm_source=telegram&utm_campaign=digest')}">grupo do WhatsApp</a>` +
  `\n⚠️ Preços mudam a qualquer momento.`;

return [{ json: { publicar: true, texto, canal: CONFIG.canal,
                  foto: escolhidos[0].foto || '', total: escolhidos.length } }];
